from pyspark.sql import functions as F


@F.udf("string")
def initials(name):
    if name is None:
        return None
    return "".join(part[0] for part in name.split()).upper()


people = spark.createDataFrame([("C9001", "ana ruiz"), ("C9002", None)], "customer_id STRING, name STRING")
people.select("customer_id", initials("name").alias("initials")).show()

spark.udf.register("initials", initials)
customers.selectExpr("customer_id", "initials(name) AS initials").show(3)

from pyspark.sql import functions as F

customers.select(
    "name",
    F.upper(F.regexp_replace(F.trim("name"), r"(\S)\S*\s*", "$1")).alias("initials"),
).show(3)


@F.udf("string")
def band(price):
    if price is None:
        return None
    return "premium" if price >= 50 else "standard" if price >= 15 else "budget"


built_in = F.when(F.col("unit_price") >= 50, "premium").when(F.col("unit_price") >= 15, "standard").otherwise("budget")
